\label{q_main1}
\begin{enumerate}
\item[(1)] Which TVS have the property that every Fr\'echet--Ury\-sohn (or metrizable) linear subspace is finite-dimensional?
\item[(2)] Which TVS have the property that every Baire linear subspace is finite-dimensional?
\end{enumerate}

\label{rem:delta}
In Corollary~\ref{cor:Delta-system}, we have $A\setminus R\neq\varnothing$ for all $A\in\mathcal{B}$. 
Indeed, if $A=R$ for some $A\in \mathcal{B}$, then $R\subsetneq B$ for any other $B\in \mathcal{B}$, and hence $|B|>|A|$.

\label{rem:finer}
If a family $\mathscr F$ absorbs convergent sequences in $(X,\tau)$, then it absorbs convergent sequences in $(X,\tau')$ for any 
topology $\tau'$ finer than~$\tau$ and $\{F\cap Y:F\in\mathscr F\}$ absorbs convergent sequences in any $Y\subset X$.

\label{lemma:ind-limit}
If a space $Z$ is the inductive limit of an increasing sequence $(K_n)_{n\in\omega}$ of its closed subspaces, 
then the family $\{K_n: n\in\omega\}$ absorbs convergent sequences in $Z$.

\label{prop:kfu-group-loc-precomp}
Suppose that a family $\{F_n: n\in \omega\}$ of closed precompact subsets of a topological group $G$ absorbs convergent 
sequences in~$G$. Then any $\varkappa$-Fr\'{e}chet--Urysohn subgroup of $G$ is locally precompact.

\label{lfd}
Let $V$ be a TVS. We say that its subgroup $G$ is \emph{locally finite-dimensional} if there exists 
a finite-dimensional subspace $E$ of $V$ for which $G\cap E$ is open in~$G$.

\label{lemma:fd-subgroup}
Let $V$ be a TVS, and let $G$ be a subgroup of $V$ topologically isomorphic to a 
finite-dimensional vector space $W$. Then $G$ is a finite-dimensional vector subspace of~$V$.

\label{th:lc-subgroups}
For  a TVS $V$ and a  subgroup $G$ of $V$, 
the following conditions are equivalent:
\begin{enumerate}
\item[\rm (i)]
$G$ is locally compact;
\item[\rm (ii)]
$G$ is locally compact and metrizable;
\item[\rm (iii)]
$G$ is a Lie group;
\item[\rm (iv)]
$G$ is a closed locally finite-dimensional  subgroup of $V$;
\item[\rm (v)]
there exists a finite-dimensional subspace $E$ of $V$ such that $E\subset G$ and $E$ is open in~$G$;
\item[\rm (vi)]
there exists a finite-dimensional subspace $E$ of $V$ and a discrete subgroup $H$ of $G$ closed in $V$
for which $G=E\oplus H$.
\end{enumerate}

\label{th:lfd-subgroups}
For  a TVS $V$ and a  subgroup $G$ of $V$, 
the following conditions are equivalent:
\begin{enumerate}
\item[\rm (i)]
$G$ is locally finite-dimensional;
\item[\rm (ii)]
the closure of $G$ in $V$ is locally compact;
\item[\rm (iii)]
$G$ is locally precompact.
\end{enumerate}

\label{prop:sg-tvs}
Let $V$ be a TVS, and let $\lVert\boldsymbol\cdot\rVert$ be a norm on $V$.
If $G$ is a subgroup of $V$ and some nonempty open set $U\subset G$ is norm-bounded, then
\begin{enumerate}
\item[{\rm(i)}]
the topology of $G$ is finer than that generated by $\lVert\boldsymbol\cdot\rVert$\textup;
\item[{\rm(ii)}]
if the topology on $V$ generated by $\lVert\boldsymbol\cdot\rVert$ is finer than the given topology of $V$, 
then the topology of $G$ coincides with  that generated by~$\lVert\boldsymbol\cdot\rVert$\textup;
\item[{\rm(iii)}]
if there exists an $r>0$ for which the ball $B(r)$ is precompact in $V$, then $G$ is locally finite-dimensional.
\end{enumerate}

\label{prop:sg-baire-tvs}
Let $V$ be a TVS, and let $\lVert\boldsymbol\cdot\rVert$ be a norm on $V$ such that
 the ball $B(r)=\{x\in V:\|x\|\leq r\}$ is closed in $V$ for any $r \geq 0$.
If $G$ is a Baire subgroup of $V$, then
\begin{enumerate}
\item[{\rm(i)}]
the topology of $G$ is finer than that generated by $\lVert\boldsymbol\cdot\rVert$\textup;
\item[{\rm(ii)}]
if the topology generated by $\lVert\boldsymbol\cdot\rVert$ on $V$ is finer than the given topology of $V$, 
then the topology of $G$ coincides with that generated by $\lVert\boldsymbol\cdot\rVert$\textup;
\item[{\rm(iii)}]
if there exists an $r>0$ for which the ball $B(r)$ is precompact, then $G$ 
is locally finite-dimensional.
\end{enumerate}

\label{prop:kfu-group-tvs}
Let $V$ be a TVS, and let $G$ be a $\varkappa$-Fr\'{e}chet--Urysohn 
subgroup of $V$. Suppose that $\lVert\boldsymbol\cdot\rVert$ is a norm on $V$ satisfying the following conditions:
\begin{enumerate}
\item[{\rm(a)}]
for any $r > 0$, the ball $B(r)$ is closed in $V$;
\item[{\rm(b)}]
the family $\mathscr F=\{B(n): n\in \omega\}$ absorbs convergent sequences in $V$. 
\end{enumerate}
Then
\begin{enumerate}
\item[{\rm(i)}]
the topology of $G$ is finer than that generated by $\lVert\boldsymbol\cdot\rVert$\textup;
\item[{\rm(ii)}]
if the topology generated by $\lVert\boldsymbol\cdot\rVert$ on $V$ is finer than the given topology of $V$, 
then the topology of $G$ coincides with that generated by $\lVert\boldsymbol\cdot\rVert$\textup;
\item[{\rm(iii)}]
if there exists an $r>0$ for which $B(r)$ is precompact, then $G$ is locally finite-dimensional.
\end{enumerate}

\label{th:criterion}
Let $V$ be a TVS, and let $\lVert\boldsymbol\cdot\rVert$ be a norm on $V$ such that
\begin{enumerate}
\item[{\rm(a)}] every ball $B(r)$, $r>0$, is closed in $V$;
\item[{\rm(b)}] the family $\{B(n): n\in \omega\}$ absorbs convergent sequences in $V$;
\item[{\rm(c)}] the ball $B(r)$ is precompact in $V$ for some \textup(equivalently, for all\textup) $r>0$.
\end{enumerate}
Then every $\varkappa$-Fr\'echet--Urysohn subgroup and every Baire subgroup of $V$ is locally finite-dimensional, 
and every $\varkappa$-Fr\'echet--Urysohn or Baire linear subspace of $V$ is finite-dimensional. The same holds for 
every linear subspace of~$V$ with the induced topology.

\label{lemma:bs-as}
Given any normed space $E$, the family $\mathscr B=\{B(n): n\in \omega\}$ consists of closed precompact 
subsets of $E_w$ and absorbs convergent sequences in~$E_w$.

\label{th:bs-kfu-baire-sgs}
Let $E$ be a normed space, and let $G$ be a subgroup of the space $E_w$.
If $G$ is $\varkappa$-Fr\'{e}chet--Urysohn or Baire, then $G$ is locally finite-dimensional.

\label{cor:bs-kfu-baire-sgs}
Let $E$ be a normed space, and let $L$ be a linear subspace of $E_w$.
If $L$ is $\varkappa$-Fr\'{e}chet--Urysohn or Baire, then $L$ is finite-dimensional.

\label{rem:Lw}
For an infinite-dimensional Banach space $E$, the fact that $E_w$ is not Baire was observed in \cite{Edgar1984}.
Also, the fact that $E_w$ is not Fr\'echet--Urysohn follows from  results of \cite[p.~280]{SW1991}.

\label{lemma:weakstar}
Let $E$ be a Banach space. Then
\begin{enumerate}
\item[\rm (i)] every ball $B(n)$ is compact in $E'_{w^*}$;
\item[\rm (ii)] every compact subset of $E'_{w^*}$ is norm-bounded and hence  contained in some $B(n)$.
\end{enumerate}
Thus, $E'_{w^*}$ is hemicompact with respect to the family $\{B(n): n\in\omega\}$. In particular, this family 
absorbs convergent sequences in~$E'_{w^*}$.

\label{th:weakstar}
Let $E$ be a Banach space. Then every $\varkappa$-Fr\'echet--Urysohn or Baire subgroup of $E'_{w^*}$ is locally 
finite-dimensional, and every $\varkappa$-Fr\'echet--Urysohn or Baire linear subspace of $E'_{w^*}$ is finite-dimensional.

\label{lemma:En-closed}
For any space $X$ and any $n\in\omega$, the set $E_n(X)$ is closed in $L_b(X)$ \textup(and hence in 
$L_p(X)$, $L(X)$, and $V(X)$\textup).

\label{lemma:lfd}
Let $\tau$ be any vector space topology on $E(X)$. Then a subgroup $G$ of $(E(X), \tau)$ is locally 
finite-dimensional if and only if $G\cap E_n(X)$ has nonempty interior in $G$ for some $n\in \omega$.

\label{th:bsg-lfd}
Let $\tau$ be a vector space topology on $E(X)$ finer than the topology of $L_b(X)$. Then any Baire subgroup 
$G$ of $(E(X), \tau)$ is locally finite-dimensional.

\label{t4}
Let $\tau$ be a vector space topology on $E(X)$ between the topologies of $L_p(X)$ and $L(X)$. Then any  
$\varkappa$-Fr\'echet--Urysohn subgroup of $(E(X), \tau)$ is locally finite-dimensional.

\label{th:lss-kfu}
Let $\tau$ be a vector space topology on $E(X)$. Suppose that one of the following conditions holds:
\begin{enumerate}
\item[{\rm(i)}]
$\tau$ is between the topologies of $L_p(X)$ and $L(X)$\textup;
\item[{\rm(ii)}]
$(E(X),\tau)=V(X)$\textup;
\item[{\rm(iii)}]
$(E(X),\tau)=L_b(X)$.
\end{enumerate}
Then any $\varkappa$-Fr\'echet--Urysohn linear subspace of $(E(X),\tau)$ is finite-di\-men\-sional.

\label{q5}
Let $\tau$ be a vector space topology on $E(X)$ between the topologies of $L_p(X)$ and $V(X)$. Is it true that 
every $\varkappa$-Fr\'echet--Urysohn subgroup of $(E(X),\tau)$ is locally finite-dimensional?
